    "siteUrl": "https://vladimiracunadev-create.github.io/modern-cybersecurity-program/classes/parte-9-forense-digital-y-respuesta-a-incidentes/208-forense-de-red/README.html",
    "githubUrl": "https://github.com/vladimiracunadev-create/modern-cybersecurity-program/blob/main/classes/parte-9-forense-digital-y-respuesta-a-incidentes/208-forense-de-red/README.md",
